    <style>
      :root {
        --bg: #fdfcf6;
        --card: #ffffff;
        --text: #233127;
        --muted: #607064;
        --primary: #3f8f5b;
        --primary-strong: #327149;
        --accent: #f3b562;
        --accent-soft: #fff1dc;
        --terracotta: #d67a52;
        --border: #e7e8df;
        --shadow: 0 12px 30px rgba(46, 67, 51, 0.1);
        --radius: 18px;
        --max: 1160px;
      }

      * { box-sizing: border-box; }
      html, body { margin: 0; padding: 0; }
      body {
        font-family: "Inter", system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
        background: var(--bg);
        color: var(--text);
        line-height: 1.55;
      }

      h1, h2, h3, .brand, .stat-number {
        font-family: "Nunito", "Inter", sans-serif;
      }

      .container {
        width: min(100% - 2rem, var(--max));
        margin-inline: auto;
      }

      .site-header {
        position: sticky;
        top: 0;
        z-index: 20;
        background: rgba(253, 252, 246, 0.92);
        backdrop-filter: blur(8px);
        border-bottom: 1px solid var(--border);
      }

      .header-inner {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 0.9rem 0;
      }

      .brand {
        font-size: 1.4rem;
        font-weight: 800;
        display: flex;
        align-items: center;
        gap: 0.5rem;
      }

      .brand-badge {
        display: inline-grid;
        place-items: center;
        width: 2rem;
        aspect-ratio: 1;
        border-radius: 999px;
        background: linear-gradient(160deg, var(--accent), #ffd977);
      }

      nav ul {
        list-style: none;
        display: flex;
        gap: 1.1rem;
        padding: 0;
        margin: 0;
      }

      nav a {
        color: var(--text);
        text-decoration: none;
        font-weight: 600;
      }

      nav a:hover { color: var(--primary); }

      .hero {
        padding: 4.2rem 0 3rem;
      }

      .hero-grid {
        display: grid;
        grid-template-columns: 1.1fr 0.9fr;
        gap: 2rem;
        align-items: center;
      }

      .hero h1 {
        font-size: clamp(2rem, 5vw, 3.45rem);
        line-height: 1.1;
        margin: 0;
      }

      .hero p {
        color: var(--muted);
        max-width: 52ch;
      }

      .btn {
        border: 0;
        border-radius: 999px;
        padding: 0.78rem 1.2rem;
        font-weight: 700;
        font-family: inherit;
        cursor: pointer;
      }

      .btn-primary {
        background: var(--primary);
        color: white;
      }

      .btn-primary:hover { background: var(--primary-strong); }

      .hero-image {
        border-radius: 24px;
        box-shadow: var(--shadow);
        width: 100%;
        height: 360px;
        object-fit: cover;
      }

      section { padding: 2.8rem 0; }
      .section-title { font-size: clamp(1.5rem, 3.4vw, 2.1rem); margin: 0; }
      .section-subtitle { color: var(--muted); margin-top: 0.4rem; }

      .carousel-shell {
        margin-top: 1.2rem;
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: var(--radius);
        padding: 1rem;
        box-shadow: var(--shadow);
      }

      .carousel-controls {
        display: flex;
        justify-content: flex-end;
        gap: 0.6rem;
        margin-bottom: 0.8rem;
      }

      .icon-btn {
        width: 2.4rem;
        aspect-ratio: 1;
        border-radius: 999px;
        border: 1px solid var(--border);
        background: #fff;
        cursor: pointer;
        font-size: 1.1rem;
      }

      .icon-btn:hover { background: #f5f8f0; }
      .carousel-viewport { overflow: hidden; }

      .carousel-track {
        display: flex;
        gap: 1rem;
        transition: transform 360ms ease;
      }

      .product-card {
        min-width: calc((100% - 2rem) / 3);
        border-radius: 14px;
        overflow: hidden;
        border: 1px solid var(--border);
        background: #fff;
      }

      .product-card img {
        width: 100%;
        height: 190px;
        object-fit: cover;
        display: block;
      }

      .product-body { padding: 0.85rem; }
      .product-name { margin: 0 0 0.3rem; font-weight: 700; }
      .product-price { margin: 0; color: var(--primary-strong); font-weight: 700; }

      .stats-banner {
        background: linear-gradient(140deg, #3f8f5b, #51a06d 56%, #79b891);
        color: #fff;
        border-radius: calc(var(--radius) + 2px);
        padding: 1.4rem;
        box-shadow: var(--shadow);
      }

      .stats-grid {
        display: grid;
        grid-template-columns: repeat(4, 1fr);
        gap: 0.8rem;
      }

      .stat-card {
        background: rgba(255, 255, 255, 0.12);
        border-radius: 12px;
        padding: 0.9rem;
      }

      .stat-number { font-size: 1.6rem; font-weight: 800; }
      .stat-label { margin-top: 0.2rem; font-size: 0.94rem; }

      .categories-grid {
        margin-top: 1.1rem;
        display: grid;
        grid-template-columns: repeat(5, 1fr);
        gap: 0.9rem;
      }

      .category-card {
        position: relative;
        border-radius: 15px;
        overflow: hidden;
        aspect-ratio: 4 / 5;
        border: 1px solid var(--border);
        transform: translateZ(0);
        transition: transform 240ms ease, box-shadow 240ms ease;
      }

      .category-card img {
        width: 100%;
        height: 100%;
        object-fit: cover;
      }

      .category-overlay {
        position: absolute;
        inset: 0;
        display: grid;
        place-items: end start;
        padding: 0.8rem;
        color: #fff;
        font-family: "Nunito", sans-serif;
        font-weight: 800;
        background: linear-gradient(to top, rgba(23, 35, 27, 0.78), rgba(23, 35, 27, 0.05));
      }

      .category-card:hover {
        transform: scale(1.03);
        box-shadow: 0 16px 30px rgba(38, 58, 45, 0.2);
      }

      .store-box, .newsletter-box {
        background: var(--card);
        border: 1px solid var(--border);
        border-radius: var(--radius);
        padding: 1rem;
      }

      .form-row {
        display: flex;
        gap: 0.6rem;
        margin: 1rem 0;
      }

      input[type="text"], input[type="email"] {
        flex: 1;
        border: 1px solid var(--border);
        border-radius: 12px;
        padding: 0.78rem 0.9rem;
        font: inherit;
      }

      table {
        width: 100%;
        border-collapse: collapse;
        font-size: 0.95rem;
      }

      th, td {
        border-bottom: 1px solid var(--border);
        text-align: left;
        padding: 0.64rem 0.4rem;
      }

      #store-results { display: none; }
      #newsletter-message {
        display: none;
        color: var(--primary-strong);
        font-weight: 600;
      }

      footer {
        margin-top: 2.2rem;
        background: #f3f1e5;
        border-top: 1px solid var(--border);
        padding: 2.1rem 0;
      }

      .footer-grid {
        display: grid;
        grid-template-columns: repeat(4, 1fr);
        gap: 1rem;
      }

      .footer-grid h3 { margin-top: 0; margin-bottom: 0.55rem; font-size: 1.05rem; }
      .footer-grid a { display: block; margin-bottom: 0.34rem; color: #344538; text-decoration: none; }
      .footer-grid a:hover { color: var(--primary); }
      .tagline { margin-top: 1.2rem; color: #4f5f53; font-size: 0.93rem; }

      @media (max-width: 1020px) {
        .hero-grid { grid-template-columns: 1fr; }
        .stats-grid { grid-template-columns: repeat(2, 1fr); }
        .categories-grid { grid-template-columns: repeat(3, 1fr); }
        .product-card { min-width: calc((100% - 1rem) / 2); }
      }

      @media (max-width: 720px) {
        nav ul { gap: 0.6rem; font-size: 0.93rem; }
        .categories-grid { grid-template-columns: repeat(2, 1fr); }
        .product-card { min-width: 100%; }
        .form-row { flex-direction: column; }
        .footer-grid { grid-template-columns: 1fr 1fr; }
      }
    </style>
  </head>
  <body>
    <header class="site-header">
      <div class="container header-inner">
        <div class="brand"><span class="brand-badge">🥬</span> Fresh Pantry</div>
        <nav>
          <ul>
            <li><a href="#featured">Products</a></li>
            <li><a href="#stores">Our Stores</a></li>
            <li><a href="#newsletter">Recipes</a></li>
            <li><a href="#footer">About Us</a></li>
          </ul>
        </nav>
      </div>
    </header>

    <main>
      <section class="hero">
        <div class="container hero-grid">
          <div>
            <h1>Discover Everyday Deliciousness</h1>
            <p>
              Your neighborhood grocery with exciting new finds, trusted pantry staples, and fresh flavors
              at great prices. Wander our curated aisles from the comfort of home.
            </p>
            <button class="btn btn-primary" onclick="document.getElementById('featured').scrollIntoView({behavior:'smooth'})">Browse Featured Products</button>
          </div>
          <img class="hero-image" src="https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1200&q=80" alt="A bright and welcoming grocery aisle with fresh produce" />
        </div>
      </section>

      <section id="featured">
        <div class="container">
          <h2 class="section-title">Featured Products</h2>
          <p class="section-subtitle">Fan favorites and pantry heroes our shoppers keep coming back for.</p>
          <div class="carousel-shell">
            <div class="carousel-controls">
              <button class="icon-btn" id="carousel-prev" aria-label="Previous products">←</button>
              <button class="icon-btn" id="carousel-next" aria-label="Next products">→</button>
            </div>
            <div class="carousel-viewport">
              <div class="carousel-track" id="carousel-track">
                <article class="product-card">
                  <img src="https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=800&q=80" alt="Organic Maple Granola in a bowl" />
                  <div class="product-body"><h3 class="product-name">Organic Maple Granola</h3><p class="product-price">$4.99</p></div>
                </article>
                <article class="product-card">
                  <img src="https://images.unsplash.com/photo-1473093295043-cdd812d0e601?auto=format&fit=crop&w=800&q=80" alt="Everything But The Bagel Seasoning sprinkled over avocado toast" />
                  <div class="product-body"><h3 class="product-name">Everything But The Bagel Seasoning</h3><p class="product-price">$2.49</p></div>
                </article>
                <article class="product-card">
                  <img src="https://images.unsplash.com/photo-1511381939415-e44015466834?auto=format&fit=crop&w=800&q=80" alt="Dark Chocolate Peanut Butter Cups on a plate" />
                  <div class="product-body"><h3 class="product-name">Dark Chocolate Peanut Butter Cups</h3><p class="product-price">$3.79</p></div>
                </article>
                <article class="product-card">
                  <img src="https://images.unsplash.com/photo-1551024601-bec78aea704b?auto=format&fit=crop&w=800&q=80" alt="Cauliflower gnocchi served with herbs" />
                  <div class="product-body"><h3 class="product-name">Cauliflower Gnocchi</h3><p class="product-price">$3.29</p></div>
                </article>
                <article class="product-card">
                  <img src="https://images.unsplash.com/photo-1604908176997-4318ea47b4d6?auto=format&fit=crop&w=800&q=80" alt="Mandarin orange chicken served in a bowl" />
                  <div class="product-body"><h3 class="product-name">Mandarin Orange Chicken</h3><p class="product-price">$5.99</p></div>
                </article>
              </div>
            </div>
          </div>
        </div>
      </section>

      <section>
        <div class="container stats-banner">
          <div class="stats-grid">
            <div class="stat-card"><div class="stat-number">500+</div><div class="stat-label">Stores Nationwide</div></div>
            <div class="stat-card"><div class="stat-number">4,000+</div><div class="stat-label">Unique Products</div></div>
            <div class="stat-card"><div class="stat-number">80%</div><div class="stat-label">Private Label Items</div></div>
            <div class="stat-card"><div class="stat-number">Weekly</div><div class="stat-label">New Items Every Week</div></div>
          </div>
        </div>
      </section>

      <section id="seasonal">
        <div class="container">
          <h2 class="section-title">Seasonal Picks</h2>
          <p class="section-subtitle">Bright flavors for this season — ready for your cart and your kitchen.</p>
        </div>
      </section>

      <section id="categories">
        <div class="container">
          <h2 class="section-title">Shop by Category</h2>
          <div class="categories-grid">
            <div class="category-card"><img src="https://images.unsplash.com/photo-1499636136210-6f4ee915583e?auto=format&fit=crop&w=700&q=80" alt="Snacks and sweets assortment" /><div class="category-overlay">Snacks &amp; Sweets</div></div>
            <div class="category-card"><img src="https://images.unsplash.com/photo-1610832958506-aa56368176cf?auto=format&fit=crop&w=700&q=80" alt="Fresh produce section" /><div class="category-overlay">Fresh Produce</div></div>
            <div class="category-card"><img src="https://images.unsplash.com/photo-1488459716781-31db52582fe9?auto=format&fit=crop&w=700&q=80" alt="Frozen meals and favorites" /><div class="category-overlay">Frozen Favorites</div></div>
            <div class="category-card"><img src="https://images.unsplash.com/photo-1551024506-0bccd828d307?auto=format&fit=crop&w=700&q=80" alt="Beverages and drinks" /><div class="category-overlay">Beverages</div></div>
            <div class="category-card"><img src="https://images.unsplash.com/photo-1486297678162-eb2a19b0a32d?auto=format&fit=crop&w=700&q=80" alt="Dairy and cheese products" /><div class="category-overlay">Dairy &amp; Cheese</div></div>
          </div>
        </div>
      </section>

      <section id="stores">
        <div class="container store-box">
          <h2 class="section-title">Find Your Fresh Pantry</h2>
          <p class="section-subtitle">Enter your zip code to discover the nearest store, hours, and directions.</p>
          <div class="form-row">
            <input type="text" id="zip-input" placeholder="Enter your zip code" maxlength="10" />
            <button class="btn btn-primary" id="search-store">Search</button>
          </div>
          <div id="store-results" aria-live="polite">
            <table>
              <thead>
                <tr><th>Store Name</th><th>Address</th><th>Hours</th><th>Distance</th></tr>
              </thead>
              <tbody>
                <tr><td>Fresh Pantry — Lincoln Park</td><td>2140 N. Halsted St, Chicago, IL 60614</td><td>8am – 9pm Daily</td><td>0.8 mi</td></tr>
                <tr><td>Fresh Pantry — Wicker Park</td><td>1840 W. North Ave, Chicago, IL 60622</td><td>8am – 9pm Daily</td><td>1.4 mi</td></tr>
                <tr><td>Fresh Pantry — Lakeview</td><td>3745 N. Lincoln Ave, Chicago, IL 60613</td><td>8am – 9pm Daily</td><td>2.1 mi</td></tr>
              </tbody>
            </table>
          </div>
        </div>
      </section>

      <section id="newsletter">
        <div class="container newsletter-box">
          <h2 class="section-title">Stay Fresh 🍋</h2>
          <p class="section-subtitle">Sign up for weekly deals, new product alerts, and seasonal recipes delivered to your inbox.</p>
          <div class="form-row">
            <input type="email" id="newsletter-email" placeholder="Your email address" />
            <button class="btn" style="background: var(--terracotta); color: #fff" id="subscribe-btn">Subscribe</button>
          </div>
          <p id="newsletter-message">Thanks for subscribing! Check your inbox for a welcome treat.</p>
        </div>
      </section>
    </main>

    <footer id="footer">
      <div class="container">
        <div class="footer-grid">
          <div>
            <h3>Shop</h3>
            <a href="#">Products</a><a href="#">Seasonal Picks</a><a href="#">New Arrivals</a><a href="#">Gift Cards</a>
          </div>
          <div>
            <h3>Company</h3>
            <a href="#">About Us</a><a href="#">Careers</a><a href="#">Press</a><a href="#">Sustainability</a>
          </div>
          <div>
            <h3>Help</h3>
            <a href="#stores">Store Locator</a><a href="#">FAQs</a><a href="#">Contact Us</a><a href="#">Accessibility</a>
          </div>
          <div>
            <h3>Follow Us</h3>
            <a href="#">Instagram</a><a href="#">Facebook</a><a href="#">Pinterest</a><a href="#">TikTok</a>
          </div>
        </div>
        <p class="tagline">© 2024 Fresh Pantry. Discover Everyday Deliciousness.</p>
      </div>
    </footer>

    <script>
      const track = document.getElementById('carousel-track');
      const cards = [...track.children];
      const prev = document.getElementById('carousel-prev');
      const next = document.getElementById('carousel-next');
      let index = 0;

      function visibleCount() {
        if (window.innerWidth <= 720) return 1;
        if (window.innerWidth <= 1020) return 2;
        return 3;
      }

      function updateCarousel() {
        const gap = parseFloat(getComputedStyle(track).gap) || 0;
        const cardWidth = cards[0].getBoundingClientRect().width;
        track.style.transform = `translateX(-${index * (cardWidth + gap)}px)`;
      }

      function maxIndex() {
        return Math.max(0, cards.length - visibleCount());
      }

      next.addEventListener('click', () => {
        index = Math.min(maxIndex(), index + 1);
        updateCarousel();
      });

      prev.addEventListener('click', () => {
        index = Math.max(0, index - 1);
        updateCarousel();
      });

      window.addEventListener('resize', () => {
        index = Math.min(index, maxIndex());
        updateCarousel();
      });

      const storeBtn = document.getElementById('search-store');
      const zipInput = document.getElementById('zip-input');
      const storeResults = document.getElementById('store-results');

      storeBtn.addEventListener('click', () => {
        if (zipInput.value.trim().length >= 3) {
          storeResults.style.display = 'block';
        }
      });

      const subscribeBtn = document.getElementById('subscribe-btn');
      const newsletterEmail = document.getElementById('newsletter-email');
      const newsletterMessage = document.getElementById('newsletter-message');

      subscribeBtn.addEventListener('click', () => {
        const val = newsletterEmail.value.trim();
        if (val.includes('@') && val.includes('.')) {
          newsletterMessage.style.display = 'block';
          newsletterEmail.value = '';
        }
      });

      updateCarousel();
    </script>
  </body>
</html>
EOF

